function openDeleteItem(id){const node=nodes.find(n=>n.id===id);if(!node)return;const ids=new Set();function tree(n){ids.add(n.id);const cs=children(n.id);return '<li><span>'+esc(n.title)+'</span>'+(cs.length?'<ul>'+cs.map(tree).join('')+'</ul>':'')+'</li>'}$('#delete-item-tree').innerHTML='<ul>'+tree(node)+'</ul>';deleteItemSelection={project:activeProjectId,id,ids};$('#delete-item-message').textContent='将删除以下 '+ids.size+' 个事项'+(!node.parent?'（包含项目根节点，将同时删除整个项目）':'')+'，请确认结构：';deleteItemDialog.showModal();$('#delete-item-cancel').focus()}
