$('#delete-item-confirm').onclick=async()=>{if(deleteItemSaving||!deleteItemSelection||deleteItemSelection.project!==activeProjectId)return;const node=nodes.find(n=>n.id===deleteItemSelection.id);if(!node)return;const {ids}=deleteItemSelection,root=!node.parent;const documentBefore=projectDocument();const nextProjects=root?projects.filter(p=>p.id!==activeProjectId):projects.map(p=>p.id===activeProjectId?{...p,items:nodes.filter(n=>!ids.has(n.id))}:p);const nextActive=root?(nextProjects[0]?.id||''):activeProjectId;deleteItemSaving=true;$('#delete-item-confirm').disabled=true;try{await window.projectStorage.save({...documentBefore,projects:nextProjects,activeProjectId:nextActive});projects=nextProjects;deleteItemDialog.close();selected=null;if(root)activateProject(nextActive);else{nodes=projects.find(p=>p.id===activeProjectId).items;ids.forEach(id=>collapsed.delete(id));render()}toast('已删除 '+ids.size+' 个事项及其记录（无法撤销）')}catch(error){toast('删除保存失败，事项已保留：'+String(error))}finally{deleteItemSaving=false;$('#delete-item-confirm').disabled=false}};
function report(person){
const previous=new Date(date+'T12:00:00Z');previous.setUTCDate(previous.getUTCDate()-1);const yesterday=previous.toISOString().slice(0,10);
function section(day,withProgress){const items=nodes.filter(n=>dailyFiltered(n)&&(!person||primaryOwner(n)===person)&&n.logs?.[day]&&(!withProgress||n.logs[day].deferredTo!==date)&&(n.logs[day].todo.trim()||(withProgress&&n.logs[day].note.trim())));if(!items.length)return withProgress?'暂无昨日 TODO 进展。':'暂无今日 TODO。';return people.filter(p=>items.some(n=>primaryOwner(n)===p)).map(p=>p+'\n'+items.filter(n=>primaryOwner(n)===p).map(n=>{const log=n.logs[day];return `${log.done?'[x]':'[ ]'} ${(log.todo||n.title).replace(/\n/g,'\n    ')}\n    事项：${path(n)}${withProgress?'\n    进展：'+(log.note||'待补充').replace(/\n/g,'\n        '):''}`}).join('\n')).join('\n\n')}
return `${date} ｜ ${nodes.find(n=>!n.parent).title}\n\n昨日 TODO 进展（${yesterday}）\n${section(yesterday,true)}\n\n今日 TODO（${date}）\n${section(date,false)}`
}
