function renderTable(){
$('#table-hide-complete').checked=$('#hide-done').checked;const tasks=[];function visit(n,ancestors){const cs=children(n.id);if(cs.length)cs.forEach(child=>visit(child,[...ancestors,n]));else if(filtered(n)&&(!tableHideInactive||!inactive(n)))tasks.push({node:n,ancestors})}visit(nodes.find(n=>!n.parent),[]);
$('#table-count').textContent=`${tasks.length} 个叶子任务`;const columns=[{key:'level-0',label:'项目'},{key:'ancestor-path',label:'上级事项'},...['任务','负责人','状态','完成度','目标','风险','日期','历史 TODO','进展'].map((label,i)=>({key:['task','owner','status','progress','goal','risk','date','todo','note'][i],label}))];if(columns.every(c=>hiddenTableColumns.has(c.key)))hiddenTableColumns.delete('task');renderColumnSettings(columns);
const rows=[];tasks.forEach(task=>{const key=activeProjectId+':'+task.node.id;const dates=Object.keys(task.node.logs||{}).sort().reverse();const shown=dates.slice(0,tableHistoryLimits.get(key)||5);(shown.length?shown:[null]).forEach((day,index)=>rows.push({...task,day,first:index===0,count:Math.max(1,shown.length),remaining:dates.length-shown.length,key}))});
function sameHierarchy(a,b,column){if(column===0)return (a.ancestors[0]?.id||a.node.id)===(b.ancestors[0]?.id||b.node.id);return a.ancestors.length===b.ancestors.length&&a.ancestors.every((n,i)=>n.id===b.ancestors[i]?.id)}
$('#task-table').innerHTML=`<thead><tr>${columns.map(c=>`<th data-column="${c.key}">${c.label}</th>`).join('')}</tr></thead><tbody>${rows.map((row,index)=>{const n=row.node;let prefix='';for(let column=0;column<2;column++){if(index&&sameHierarchy(row,rows[index-1],column))continue;let span=1;while(index+span<rows.length&&sameHierarchy(row,rows[index+span],column))span++;const chain=column===0?[row.ancestors[0]||n]:row.ancestors.slice(1);const content=chain.map(ancestor=>`<button data-table-item="${esc(ancestor.id)}">${esc(ancestor.title)}</button>`).join('<span class="path-separator"> / </span>');prefix+=`<td class="hierarchy-cell ${column===1?'ancestor-path-cell':''} ${!chain.length?'blank':''}" rowspan="${span}">${content||'—'}</td>`}const status=inactive(n)?'未进行':n.progress===100?'已完成':'进行中';const log=n.logs?.[row.day]||{};const cells=row.first?`<td class="leaf-cell" rowspan="${row.count}"><button data-table-item="${esc(n.id)}">${esc(n.title)}</button><button class="table-todo-add" data-table-todo="${esc(n.id)}" aria-label="为 ${esc(n.title)} 新增今日 TODO">＋ 今日 TODO</button>${row.remaining?`<button class="history-more" data-history-more="${esc(n.id)}" aria-label="加载 ${esc(n.title)} 的更多历史记录">more <span>· 还有 ${row.remaining} 条</span></button>`:''}</td><td class="owner-cell" rowspan="${row.count}">${owners(n).map((person,index)=>`<span class="table-owner" title="${index===0?'首要责任人':'协作负责人'}">${avatar(person)}${esc(person)}${index===0?'<i class="primary-owner-badge">主</i>':''}</span>`).join('')}</td><td class="state-cell" rowspan="${row.count}"><i class="table-dot ${inactive(n)?'gray':n.progress===100?'done':'green'}"></i>${status}</td><td rowspan="${row.count}">${inactive(n)?'—':n.progress+'%'}</td><td class="long-cell" rowspan="${row.count}">${esc(n.goal||'')||'—'}</td><td class="long-cell risk-cell" rowspan="${row.count}">${esc(n.risk||'')||'—'}</td>`:'';return `<tr data-leaf="${esc(n.id)}" ${row.day?`data-history-date="${row.day}"`:''}>${prefix}${cells}<td class="history-date">${row.day||'—'}</td><td class="long-cell history-edit-cell">${row.day?`<textarea class="table-history-editor" data-history-field="todo" aria-label="${esc(n.title)} ${row.day} 历史 TODO" rows="1" placeholder="填写 TODO">${esc(log.todo||'')}</textarea>`:'—'}</td><td class="long-cell history-edit-cell">${row.day?`<textarea class="table-history-editor" data-history-field="note" aria-label="${esc(n.title)} ${row.day} 进展" rows="1" placeholder="填写进展">${esc(log.note||'')}</textarea>`:'—'}</td></tr>`}).join('')||`<tr><td colspan="${columns.length}" class="empty">当前筛选条件下没有叶子任务</td></tr>`}</tbody>`;
applyTableColumns();$('#task-table').querySelectorAll('[data-history-field]').forEach(input=>{function resize(){input.style.height='0px';input.style.height=Math.max(42,input.scrollHeight)+'px'}resize();input.oninput=()=>{const row=input.closest('[data-leaf]'),n=nodes.find(n=>n.id===row.dataset.leaf);const log=n.logs[row.dataset.historyDate];log[input.dataset.historyField]=input.value;resize();save();updateStats();renderDaily();if(selected===n.id)renderDetail()}});$('#task-table').querySelectorAll('[data-table-todo]').forEach(button=>button.onclick=()=>openTableTodo(button.dataset.tableTodo));$('#task-table').querySelectorAll('[data-table-item]').forEach(button=>button.onclick=()=>{selected=button.dataset.tableItem;setView('map')});$('#task-table').querySelectorAll('[data-history-more]').forEach(button=>button.onclick=()=>{const key=activeProjectId+':'+button.dataset.historyMore;const scroll=$('.task-table-scroll'),x=scroll.scrollLeft,y=scroll.scrollTop;tableHistoryLimits.set(key,(tableHistoryLimits.get(key)||5)+5);renderTable();scroll.scrollLeft=x;scroll.scrollTop=y;$('#task-table').querySelector(`[data-history-more="${button.dataset.historyMore}"]`)?.focus({preventScroll:true})})
}
async function exportTaskExcel(){
const button=$('#export-excel');button.disabled=true;try{
const columns=[...$('#task-table').querySelectorAll('thead th')].filter(cell=>!cell.classList.contains('hidden')).map(cell=>({key:cell.dataset.column,label:cell.textContent}));const records=[];
function visit(n,ancestors){const cs=children(n.id);if(cs.length){cs.forEach(child=>visit(child,[...ancestors,n]));return}if(!filtered(n)||(tableHideInactive&&inactive(n)))return;const days=Object.keys(n.logs||{}).sort().reverse();(days.length?days:[null]).forEach(day=>{const log=n.logs?.[day]||{};const values={'level-0':nodes.find(item=>!item.parent).title,'ancestor-path':ancestors.slice(1).map(item=>item.title).join(' / ')||'—',task:n.title,owner:owners(n).map((person,index)=>person+(index===0?'（首要）':'')).join(' / '),status:inactive(n)?'未进行':n.progress===100?'已完成':'进行中',progress:inactive(n)?'—':n.progress+'%',goal:n.goal||'—',risk:n.risk||'—',date:day||'—',todo:log.todo||'',note:log.note||''};records.push({node:n,ancestors,values})})}visit(nodes.find(n=>!n.parent),[]);
if(!records.length){toast('当前筛选下没有可导出的任务');return}const rows=records.map(record=>columns.map(col=>record.values[col.key]));const merges=[];
columns.forEach((col,index)=>{if(['date','todo','note'].includes(col.key))return;const identity=record=>col.key==='level-0'?'project':col.key==='ancestor-path'?JSON.stringify(record.ancestors.map(item=>item.id)):record.node.id;for(let start=0;start<records.length;){let end=start;while(end+1<records.length&&identity(records[end+1])===identity(records[start]))end++;if(end>start){merges.push({col:index,start,end});for(let i=start+1;i<=end;i++)rows[i][index]=''}start=end+1}});
const bytes=window.ProjectExcel.build(columns,rows,merges);const timestamp=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date()).replace(/[^0-9]/g,'');const project=nodes.find(n=>!n.parent).title.replace(/[\\/:*?"<>|\u0000-\u001f]/g,'_').slice(0,60)||'项目';const filename=project+'-任务表格-'+timestamp+'.xlsx';const result=await window.projectStorage.exportExcel(bytes,filename);toast(result?'Excel 已导出：'+result:'Excel 已下载（含全部历史记录）')
}catch(error){toast('导出失败：'+String(error))}finally{button.disabled=false}
}
$('#export-excel').onclick=exportTaskExcel;
