function clearCardDrag(){document.querySelector('.card-drag-preview')?.remove();canvas.querySelectorAll('.drop-target,.reparent-source').forEach(el=>el.classList.remove('drop-target','reparent-source'));canvas.classList.remove('dragging');document.body.classList.remove('map-drag-active')}
function cancelMapDrag(){if(!drag)return;const cancelled=drag;drag=null;suppressClick=cancelled.moved;if(!cancelled.node){panX=cancelled.panX;panY=cancelled.panY;applyViewport()}if(canvas.hasPointerCapture(cancelled.id))canvas.releasePointerCapture(cancelled.id);clearCardDrag()}
window.addEventListener('keydown',e=>{if(!drag)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();cancelMapDrag()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a')e.preventDefault()},true);
window.addEventListener('pointerdown',e=>{if(drag&&e.button===2){e.preventDefault();cancelMapDrag();suppressDragContextMenu=true}},true);
let suppressDragContextMenu=false;
