document.addEventListener('selectstart',e=>{if(drag)e.preventDefault()});canvas.addEventListener('dragstart',e=>{if(drag)e.preventDefault()});
function findDropTarget(x,y,source){const bounds=canvas.getBoundingClientRect();if(x<bounds.left||x>bounds.right||y<bounds.top||y>bounds.bottom)return null;let nearest=null,distance=33;canvas.querySelectorAll('[data-node]').forEach(el=>{const node=nodes.find(n=>n.id===el.dataset.node);let current=node;while(current){if(current.id===source)return;current=nodes.find(n=>n.id===current.parent)}const r=el.closest('.node').getBoundingClientRect(),gap=Math.hypot(Math.max(r.left-x,0,x-r.right),Math.max(r.top-y,0,y-r.bottom));if(gap<distance){distance=gap;nearest=node.id}});return nearest}
canvas.addEventListener('pointerdown',e=>{stopWheelZoom();if(e.button!==0||e.target.closest('input,select,textarea,button,[contenteditable]'))return;const card=e.target.closest('.node')?.querySelector('[data-node]'),node=card&&nodes.find(n=>n.id===card.dataset.node);if(node&&!node.parent)return;e.preventDefault();window.getSelection()?.removeAllRanges();document.body.classList.add('map-drag-active');drag={id:e.pointerId,x:e.clientX,y:e.clientY,panX,panY,moved:false,node:node?.id,target:null};suppressClick=false;suppressDragContextMenu=false});
window.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<5)return;e.preventDefault();if(!drag.moved){drag.moved=true;canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');if(drag.node){const preview=document.createElement('div');preview.className='card-drag-preview';preview.textContent=nodes.find(n=>n.id===drag.node).title;document.body.append(preview);canvas.querySelector(`[data-node="${drag.node}"]`).closest('.node').classList.add('reparent-source')}}if(drag.node){const preview=document.querySelector('.card-drag-preview');preview.style.left=(e.clientX+16)+'px';preview.style.top=(e.clientY+16)+'px';drag.target=findDropTarget(e.clientX,e.clientY,drag.node);canvas.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));if(drag.target)canvas.querySelector(`[data-node="${drag.target}"]`).closest('.node').classList.add('drop-target');preview.textContent=nodes.find(n=>n.id===drag.node).title+(drag.target?' → '+nodes.find(n=>n.id===drag.target).title:' · 拖到目标事项上或附近')}else{panX=drag.panX+dx;panY=drag.panY+dy;applyViewport()}});
function endDrag(e){if(!drag||e.pointerId!==drag.id)return;const finished=drag;drag=null;suppressClick=finished.moved;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);clearCardDrag();if(e.type==='pointerup'&&finished.moved&&finished.node){const target=findDropTarget(e.clientX,e.clientY,finished.node),node=nodes.find(n=>n.id===finished.node);if(!target||node.parent===target)return;node.parent=target;if(inactive(nodes.find(n=>n.id===target))){const stop=n=>{n.status='not_started';children(n.id).forEach(stop)};stop(node)}collapsed.delete(target);save();render();toast('已移到「'+nodes.find(n=>n.id===target).title+'」下')}}
